<?php if (!empty($flash)): ?><script>document.addEventListener('DOMContentLoaded',()=>{const f=<?=json_encode($flash,JSON_UNESCAPED_UNICODE)?>;if(window.Swal){Swal.fire({icon:f.type,title:f.title,text:f.message,confirmButtonColor:'#0d3b66'});}});</script><?php endif; ?><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script></body></html>
